package com.futureplus.client;

import java.util.Random;

/**
 * Skybox "Texture" mode: 4 color families x 15 designs = 60 skies, generated by CODE in high resolution
 * (equirectangular, default 4096x2048) the moment one is picked in game; the jar doesn't bloat.
 *
 * Fully plain Java (independent of Minecraft): returns int[] ARGB. Generation happens in direction space
 * (a 3D point on the sphere), so there are no seams and no pinching at the poles.
 */
public final class SkyTextures {
    private SkyTextures() {}

    public static final String[] FAMILIES = {"Red", "Green", "Blue", "Black"};
    public static final String[] DESIGNS = {
        "Nebula", "Milky Way", "Star trails", "Aurora", "Spiral galaxy",
        "Cosmic dust", "Sunset", "Rising planet", "Twin nebula", "Eclipse",
        "Ringed giant", "Supernova remnant", "Deep space", "Storm", "Void"
    };

    // ------------------------------------------------------------- palet

    /** {deep, dark, mid, bright, accent, star} */
    private static int[] palette(int fam) {
        switch (fam) {
            case 0: return new int[]{0x050104, 0x1c0510, 0x6e1430, 0xff4f6e, 0xff9a52, 0xffe2e6};
            case 1: return new int[]{0x010503, 0x05180f, 0x0f5a36, 0x3dffa6, 0x9dff5a, 0xe2fff0};
            case 2: return new int[]{0x01020a, 0x050c26, 0x15357a, 0x4fa8ff, 0xa66dff, 0xe6f0ff};
            default: return new int[]{0x000000, 0x07070a, 0x23252c, 0xc9ced8, 0x707789, 0xffffff};
        }
    }

    // ------------------------------------------------------------- noise (3D Perlin)

    private static final int[] P = new int[512];
    static {
        int[] p = new int[256];
        for (int i = 0; i < 256; i++) p[i] = i;
        Random r = new Random(1337);
        for (int i = 255; i > 0; i--) { int j = r.nextInt(i + 1); int t = p[i]; p[i] = p[j]; p[j] = t; }
        for (int i = 0; i < 512; i++) P[i] = p[i & 255];
    }

    private static double fade(double t) { return t * t * t * (t * (t * 6 - 15) + 10); }
    private static double lerp(double t, double a, double b) { return a + t * (b - a); }
    private static double grad(int h, double x, double y, double z) {
        int hh = h & 15;
        double u = hh < 8 ? x : y, v = hh < 4 ? y : (hh == 12 || hh == 14 ? x : z);
        return ((hh & 1) == 0 ? u : -u) + ((hh & 2) == 0 ? v : -v);
    }

    static double noise(double x, double y, double z) {
        int X = (int) Math.floor(x) & 255, Y = (int) Math.floor(y) & 255, Z = (int) Math.floor(z) & 255;
        x -= Math.floor(x); y -= Math.floor(y); z -= Math.floor(z);
        double u = fade(x), v = fade(y), w = fade(z);
        int A = P[X] + Y, AA = P[A] + Z, AB = P[A + 1] + Z, B = P[X + 1] + Y, BA = P[B] + Z, BB = P[B + 1] + Z;
        return lerp(w, lerp(v, lerp(u, grad(P[AA], x, y, z), grad(P[BA], x - 1, y, z)),
                               lerp(u, grad(P[AB], x, y - 1, z), grad(P[BB], x - 1, y - 1, z))),
                       lerp(v, lerp(u, grad(P[AA + 1], x, y, z - 1), grad(P[BA + 1], x - 1, y, z - 1)),
                               lerp(u, grad(P[AB + 1], x, y - 1, z - 1), grad(P[BB + 1], x - 1, y - 1, z - 1))));
    }

    static double fbm(double x, double y, double z, int oct) {
        double s = 0, a = 0.5, f = 1;
        for (int i = 0; i < oct; i++) { s += a * noise(x * f, y * f, z * f); f *= 2.03; a *= 0.5; }
        return s; // ~[-0.5, 0.5]
    }

    static double ridged(double x, double y, double z, int oct) {
        double s = 0, a = 0.5, f = 1;
        for (int i = 0; i < oct; i++) { double n = 1 - Math.abs(noise(x * f, y * f, z * f) * 1.6); s += a * n * n; f *= 2.1; a *= 0.5; }
        return s; // ~[0, 1]
    }

    // ------------------------------------------------------------- color helpers

    private static double[] rgb(int c) { return new double[]{((c >> 16) & 255) / 255.0, ((c >> 8) & 255) / 255.0, (c & 255) / 255.0}; }
    private static double clamp(double v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
    private static double smooth(double a, double b, double x) { double t = clamp((x - a) / (b - a)); return t * t * (3 - 2 * t); }

    private static void mixInto(double[] c, double[] col, double t) {
        t = clamp(t);
        c[0] += (col[0] - c[0]) * t; c[1] += (col[1] - c[1]) * t; c[2] += (col[2] - c[2]) * t;
    }
    private static void add(double[] c, double[] col, double k) { c[0] += col[0] * k; c[1] += col[1] * k; c[2] += col[2] * k; }

    /** Color ramp: 0 deep -> 1 dark -> 2 mid -> 3 bright */
    private static void ramp(double[] out, double[][] pal, double t) {
        t = clamp(t) * 3;
        int i = Math.min(2, (int) t);
        double f = t - i;
        for (int k = 0; k < 3; k++) out[k] = pal[i][k] + (pal[i + 1][k] - pal[i][k]) * f;
    }

    // ------------------------------------------------------------- stars

    /** Scatters stars as points on a separate layer (even distribution on the sphere, Gaussian blob). */
    private static void stars(float[] r, float[] g, float[] b, int W, int H, long seed, int count,
                              double[] tint, double minY, double brightness, boolean spikes) {
        Random rnd = new Random(seed);
        for (int i = 0; i < count; i++) {
            double y = rnd.nextDouble() * 2 - 1;
            if (y < minY) continue;
            double lon = rnd.nextDouble() * Math.PI * 2;
            double u = rnd.nextDouble();
            double mag = Math.pow(u, 9);                          // most very dim, very few bright
            double bri = (0.035 + 0.25 * u * u + mag * 2.4) * brightness;
            double size = 0.5 + mag * 1.3;
            // color temperature: a slight blue/yellow shift
            double ct = rnd.nextDouble();
            double cr = tint[0] * (0.85 + 0.3 * ct), cg = tint[1] * (0.9 + 0.1 * ct), cb = tint[2] * (1.15 - 0.3 * ct);
            double lat = Math.asin(y);
            double px = lon / (Math.PI * 2) * W, py = (0.5 - lat / Math.PI) * H;
            double stretch = 1.0 / Math.max(0.08, Math.cos(lat));   // equirect yatay gerilme
            int rad = (int) Math.ceil(size * 3);
            for (int dy = -rad; dy <= rad; dy++) {
                int yy = (int) py + dy;
                if (yy < 0 || yy >= H) continue;
                int radX = (int) Math.ceil(rad * stretch);
                for (int dx = -radX; dx <= radX; dx++) {
                    int xx = Math.floorMod((int) px + dx, W);
                    double ddx = ((int) px + dx + 0.5 - px) / stretch, ddy = yy + 0.5 - py;
                    double d2 = ddx * ddx + ddy * ddy;
                    double v = bri * Math.exp(-d2 / (2 * size * size * 0.3));
                    if (spikes && mag > 0.5) { // star spikes only on the brightest
                        double sp = Math.exp(-Math.abs(ddy) * 1.6) * Math.exp(-Math.abs(ddx) / (size * 5))
                                  + Math.exp(-Math.abs(ddx) * 1.6) * Math.exp(-Math.abs(ddy) / (size * 5));
                        v += bri * 0.35 * sp;
                    }
                    if (v < 0.002) continue;
                    int k = yy * W + xx;
                    r[k] += (float) (v * cr); g[k] += (float) (v * cg); b[k] += (float) (v * cb);
                }
            }
        }
    }

    // ------------------------------------------------------------- main generator

    /**
     * @param fam 0..3 color family, @param design 0..14, W x H equirectangular (W = 2H recommended).
     * @return ARGB pikseller (opak)
     */
    public static int[] generate(int fam, int design, int W, int H) {
        int[] palI = palette(fam);
        double[][] pal = new double[6][];
        for (int i = 0; i < 6; i++) pal[i] = rgb(palI[i]);
        double[][] ramp4 = {pal[0], pal[1], pal[2], pal[3]};
        double[] accent = pal[4], starC = pal[5];
        long seed = 1000L * fam + design * 7919L + 17;

        float[] R = new float[W * H], G = new float[W * H], B = new float[W * H];

        // design specific constants
        Random dr = new Random(seed);
        double ox = dr.nextDouble() * 100, oy = dr.nextDouble() * 100, oz = dr.nextDouble() * 100;
        // "focus" direction (galaxy, planet, eclipse etc. in this direction)
        double fLon = 0.6 + dr.nextDouble() * 0.5, fLat = Math.toRadians(design == 7 ? 4 : 28);
        double fx = Math.cos(fLat) * Math.cos(fLon), fy = Math.sin(fLat), fz = Math.cos(fLat) * Math.sin(fLon);
        // pole for star trails
        double pLat = Math.toRadians(38), pLon = 2.2;
        double px0 = Math.cos(pLat) * Math.cos(pLon), py0 = Math.sin(pLat), pz0 = Math.cos(pLat) * Math.sin(pLon);
        // milky way band axis (a tilted great circle)
        double ba = 0.9, bx0 = Math.sin(ba) * 0.3, by0 = Math.cos(ba), bz0 = Math.sin(ba) * 0.95;
        double bl = Math.sqrt(bx0 * bx0 + by0 * by0 + bz0 * bz0);
        final double bx1 = bx0 / bl, by1 = by0 / bl, bz1 = bz0 / bl;

        float[] trail = design == 2 ? buildTrails(W, H, seed, px0, py0, pz0) : null;

        // rows are generated in parallel (all cores): 4096x2048 finishes in a few seconds
        java.util.stream.IntStream.range(0, H).parallel().forEach(j -> {
            double bx = bx1, by = by1, bz = bz1;
            double[] c = new double[3], tmp = new double[3];
            double lat = Math.PI / 2 - (j + 0.5) / H * Math.PI;
            double cl = Math.cos(lat), y = Math.sin(lat);
            for (int i = 0; i < W; i++) {
                double lon = (i + 0.5) / W * Math.PI * 2;
                double x = cl * Math.cos(lon), z = cl * Math.sin(lon);
                int k = j * W + i;
                double hz = smooth(-0.35, 0.25, y);         // dark fade below the horizon (0 at the bottom, 1 at the top)

                c[0] = pal[0][0]; c[1] = pal[0][1]; c[2] = pal[0][2];

                switch (design) {
                    case 0: { // Nebula: domain warped fbm
                        double s = 2.2;
                        double wx = fbm(x * s + ox, y * s + oy, z * s + oz, 4);
                        double wy = fbm(x * s + oy, y * s + oz, z * s + ox, 4);
                        double n = fbm(x * s + wx * 2.2 + ox, y * s + wy * 2.2, z * s + oz, 7) + 0.5;
                        double d = fbm(x * 6 + 40, y * 6, z * 6, 5);
                        double t = smooth(0.38, 0.95, n) * (0.75 + 0.5 * d);
                        ramp(tmp, ramp4, t); mixInto(c, tmp, 1);
                        mixInto(c, accent, smooth(0.62, 0.95, n) * 0.35);
                        // dark dust lanes
                        double dust = ridged(x * 3 + oz, y * 3, z * 3 + ox, 5);
                        c[0] *= 1 - 0.55 * smooth(0.55, 0.9, dust) * t; c[1] *= 1 - 0.55 * smooth(0.55, 0.9, dust) * t; c[2] *= 1 - 0.55 * smooth(0.55, 0.9, dust) * t;
                        break;
                    }
                    case 1: { // Milky way: a tilted bright band + dust rift
                        double dist = x * bx + y * by + z * bz;           // perpendicular distance to the band
                        double band = Math.exp(-dist * dist / 0.035);
                        double n = fbm(x * 4 + ox, y * 4 + oy, z * 4 + oz, 7) + 0.5;
                        double core = band * (0.55 + 0.9 * n);
                        ramp(tmp, ramp4, core * 0.85); mixInto(c, tmp, 1);
                        double rift = Math.exp(-Math.pow(dist + 0.03 * fbm(x * 9, y * 9, z * 9, 4), 2) / 0.0012);
                        double dk = 1 - 0.75 * rift * smooth(0.45, 0.7, n);
                        c[0] *= dk; c[1] *= dk; c[2] *= dk;
                        add(c, accent, band * band * 0.12 * n);
                        break;
                    }
                    case 2: { // Star trails: arcs around the pole + horizon glow
                        double glow = Math.exp(-Math.abs(y - 0.01) * (y > 0 ? 11 : 30));
                        ramp(tmp, ramp4, 0.15 + 0.05 * (1 - y)); mixInto(c, tmp, 1);
                        double gn = 0.7 + 0.6 * (fbm(x * 3 + ox, y * 8, z * 3, 4) + 0.5);
                        add(c, accent, glow * 0.45 * gn);
                        add(c, pal[3], glow * glow * 0.15);
                        double tr = trail[k];
                        add(c, starC, tr);
                        break;
                    }
                    case 3: { // Aurora: vertical curtains
                        ramp(tmp, ramp4, 0.12 + 0.12 * (1 - Math.abs(y))); mixInto(c, tmp, 1);
                        double a = Math.atan2(z, x);
                        double curtain = 0;
                        for (int l = 0; l < 3; l++) {
                            double ph = a * (2 + l) + fbm(Math.cos(a) * 2 + l * 9, Math.sin(a) * 2, l, 4) * 5;
                            double base = 0.08 + 0.12 * l + 0.06 * fbm(Math.cos(a) * 3, Math.sin(a) * 3, l * 4 + 1, 3);
                            double h = y - base;
                            if (h < 0) continue;
                            double rays = 0.5 + 0.5 * Math.sin(ph * 6 + fbm(Math.cos(a) * 25, Math.sin(a) * 25, l, 3) * 8);
                            double prof = Math.exp(-h * 7.5) * smooth(0, 0.02, h);
                            curtain += prof * (0.35 + 0.65 * rays) * (0.6 - l * 0.12);
                        }
                        add(c, pal[3], curtain * 0.9);
                        add(c, accent, curtain * curtain * 0.35);
                        break;
                    }
                    case 4: { // Spiral galaxy: in the focus direction
                        double[] uv = local(x, y, z, fx, fy, fz, 1.0);
                        double gx = uv[0], gy = uv[1];
                        if (uv[2] > 0) {
                            double tilt = 0.45;                         // tilted disk
                            double qx = gx, qy = gy / tilt;
                            double r = Math.sqrt(qx * qx + qy * qy) * 2.4;
                            double th = Math.atan2(qy, qx);
                            double arms = Math.pow(0.5 + 0.5 * Math.cos(2 * th - 4.2 * Math.log(r + 0.08)
                                + 1.5 * fbm(qx * 6, qy * 6, 3, 4)), 2.2);
                            double disk = Math.exp(-r * 1.6) * (0.35 + 0.95 * arms) * (0.75 + 0.6 * (fbm(qx * 14, qy * 14, 7, 5) + 0.5));
                            double bulge = Math.exp(-r * r * 22);
                            ramp(tmp, ramp4, clamp(disk * 1.3)); add(c, tmp, 0.9);
                            add(c, accent, bulge * 0.9);
                            add(c, new double[]{1, 1, 1}, bulge * 0.6);
                        }
                        double n = fbm(x * 3 + ox, y * 3, z * 3, 5) + 0.5;
                        ramp(tmp, ramp4, smooth(0.5, 1, n) * 0.35); add(c, tmp, 0.4);
                        break;
                    }
                    case 5: { // Cosmic dust: bright filaments
                        double rr = ridged(x * 2.4 + ox, y * 2.4 + oy, z * 2.4 + oz, 7);
                        double n = fbm(x * 1.5 + oz, y * 1.5, z * 1.5, 4) + 0.5;
                        double t = Math.pow(rr, 3.2) * (0.6 + 0.8 * n);
                        ramp(tmp, ramp4, t * 1.2); mixInto(c, tmp, 1);
                        add(c, accent, Math.pow(rr, 7) * 0.4);
                        break;
                    }
                    case 6: { // Sunset: sky gradient + cloud layer
                        double sunD = 1 - (x * fx + z * fz) / Math.sqrt(fx * fx + fz * fz) * Math.sqrt(1 - y * y);
                        double hg = Math.exp(-Math.max(0, y) * 4.5);
                        ramp(tmp, ramp4, 0.25 + 0.6 * hg); mixInto(c, tmp, 1);
                        add(c, accent, hg * Math.exp(-sunD * 2.5) * 0.9);
                        if (y > 0.02) {
                            double cy = 1 / (y + 0.06);                // projection onto a flat cloud layer
                            double cx2 = x * cy * 0.6, cz2 = z * cy * 0.6;
                            double cn = fbm(cx2 + ox, 3.3, cz2 + oz, 7) + 0.5;
                            double cloud = smooth(0.48, 0.75, cn) * smooth(0.02, 0.15, y) * (1 - smooth(0.5, 0.95, y));
                            double lit = 0.35 + 0.65 * Math.exp(-sunD * 1.6);
                            double[] cc = {pal[2][0] * 0.6 + accent[0] * 0.5 * lit, pal[2][1] * 0.6 + accent[1] * 0.5 * lit, pal[2][2] * 0.6 + accent[2] * 0.5 * lit};
                            mixInto(c, cc, cloud * 0.9);
                        }
                        double sun = Math.exp(-sunD * 900) * smooth(-0.03, 0.02, y);
                        add(c, new double[]{1, 0.95, 0.85}, sun * 1.5);
                        break;
                    }
                    case 7: { // Rising planet: a giant planet on the horizon + atmosphere
                        ramp(tmp, ramp4, 0.1); mixInto(c, tmp, 1);
                        double n = fbm(x * 3 + ox, y * 3, z * 3, 5) + 0.5;
                        ramp(tmp, ramp4, smooth(0.55, 1, n) * 0.4); add(c, tmp, 0.5);
                        double[] uv = local(x, y, z, fx, -0.55, fz, 1.0);
                        double pr = 0.62;
                        double d = Math.sqrt(uv[0] * uv[0] + uv[1] * uv[1]);
                        if (uv[2] > 0) {
                            double rim = Math.exp(-Math.abs(d - pr) * 60) * smooth(-0.2, 0.4, uv[1]);
                            if (d < pr) {
                                double h = Math.sqrt(1 - (d / pr) * (d / pr));
                                double band = fbm(uv[0] * 2, uv[1] * 14, 5, 6) + 0.5;
                                double light = clamp(0.15 + 0.85 * (uv[1] / pr * 0.7 + h * 0.5));
                                ramp(tmp, ramp4, 0.25 + 0.55 * band);
                                c[0] = tmp[0] * light; c[1] = tmp[1] * light; c[2] = tmp[2] * light;
                            }
                            add(c, pal[3], rim * 0.9);
                            add(c, accent, Math.exp(-Math.max(0, d - pr) * 18) * smooth(-0.1, 0.5, uv[1]) * 0.25 * (d >= pr ? 1 : 0));
                        }
                        break;
                    }
                    case 8: { // Twin nebula
                        double[] u1 = local(x, y, z, fx, fy, fz, 1), u2 = local(x, y, z, -fz, 0.15, fx, 1);
                        double n1 = blob(u1, 0.55, ox), n2 = blob(u2, 0.45, oy);
                        double n = Math.max(n1, n2);
                        ramp(tmp, ramp4, n); mixInto(c, tmp, 1);
                        add(c, accent, Math.pow(n2, 3) * 0.6);
                        break;
                    }
                    case 9: { // Eclipse: dark disk + corona
                        ramp(tmp, ramp4, 0.08 + 0.1 * Math.exp(-Math.max(0, y) * 3)); mixInto(c, tmp, 1);
                        double[] uv = local(x, y, z, fx, fy, fz, 1);
                        double d = Math.sqrt(uv[0] * uv[0] + uv[1] * uv[1]);
                        double R0 = 0.11;
                        if (uv[2] > 0) {
                            double ang = Math.atan2(uv[1], uv[0]);
                            double streak = 0.6 + 0.4 * (fbm(Math.cos(ang) * 6, Math.sin(ang) * 6, 1, 5) + 0.5);
                            double cor = Math.exp(-(d - R0) * 14 / streak) * (d > R0 ? 1 : 0);
                            add(c, pal[3], cor * 1.1);
                            add(c, new double[]{1, 1, 1}, Math.exp(-Math.abs(d - R0) * 260) * 1.2);
                            add(c, accent, Math.exp(-(d - R0) * 5) * 0.25 * (d > R0 ? 1 : 0));
                            if (d < R0) { c[0] *= 0.02; c[1] *= 0.02; c[2] *= 0.02; }
                        }
                        break;
                    }
                    case 10: { // Ringed giant
                        ramp(tmp, ramp4, 0.08); mixInto(c, tmp, 1);
                        double n = fbm(x * 2.5 + ox, y * 2.5, z * 2.5, 5) + 0.5;
                        ramp(tmp, ramp4, smooth(0.5, 1, n) * 0.4); add(c, tmp, 0.5);
                        double[] uv = local(x, y, z, fx, fy * 0.6, fz, 1);
                        if (uv[2] > 0) {
                            double gx = uv[0], gy = uv[1];
                            double ringT = 0.22;                          // ring tilt
                            double rr = Math.sqrt(gx * gx + (gy / ringT) * (gy / ringT));
                            double pr = 0.2, d = Math.sqrt(gx * gx + gy * gy);
                            boolean front = gy < 0;
                            double ring = (rr > 0.28 && rr < 0.52) ? (0.5 + 0.5 * Math.sin(rr * 160) * Math.sin(rr * 41)) * smooth(0.28, 0.31, rr) * (1 - smooth(0.49, 0.52, rr)) : 0;
                            if (!front || d > pr) { ramp(tmp, ramp4, 0.55 + 0.4 * ring); mixInto(c, tmp, ring * 0.85); }
                            if (d < pr) {
                                double h = Math.sqrt(1 - (d / pr) * (d / pr));
                                double band = 0.5 + 0.5 * Math.sin(gy / pr * 18 + fbm(gx * 10, gy * 30, 2, 4) * 4);
                                double light = clamp(0.1 + 0.9 * (gx / pr * -0.6 + h * 0.7));
                                ramp(tmp, ramp4, 0.35 + 0.45 * band);
                                c[0] = tmp[0] * light; c[1] = tmp[1] * light; c[2] = tmp[2] * light;
                                if (front && ring > 0) { ramp(tmp, ramp4, 0.55 + 0.4 * ring); mixInto(c, tmp, ring * 0.85); }
                            }
                        }
                        break;
                    }
                    case 11: { // Supernova remnant: a filamentary shell
                        double[] uv = local(x, y, z, fx, fy, fz, 1);
                        double d = Math.sqrt(uv[0] * uv[0] + uv[1] * uv[1]);
                        double n = fbm(uv[0] * 4 + ox, uv[1] * 4, 2, 6);
                        double shell = Math.exp(-Math.pow((d + n * 0.12 - 0.3) * 9, 2));
                        double fil = ridged(uv[0] * 7 + oy, uv[1] * 7, 4, 6);
                        double t = shell * (0.4 + 0.9 * Math.pow(fil, 3)) * (uv[2] > 0 ? 1 : 0);
                        double bg = fbm(x * 2 + oz, y * 2, z * 2, 5) + 0.5;
                        ramp(tmp, ramp4, smooth(0.45, 1, bg) * 0.3); mixInto(c, tmp, 1);
                        ramp(tmp, ramp4, clamp(t * 1.2)); add(c, tmp, 0.9);
                        add(c, accent, t * t * 0.5);
                        add(c, new double[]{1, 1, 1}, Math.exp(-d * 120) * 1.5 * (uv[2] > 0 ? 1 : 0));
                        break;
                    }
                    case 12: { // Deep space: many small galaxies (in the star layer)
                        double n = fbm(x * 1.6 + ox, y * 1.6, z * 1.6, 5) + 0.5;
                        ramp(tmp, ramp4, smooth(0.35, 1, n) * 0.28); mixInto(c, tmp, 1);
                        break;
                    }
                    case 13: { // Storm: billowing clouds + lightning flashes
                        double s = 1.8;
                        double n = fbm(x * s + ox, y * s * 1.6 + oy, z * s + oz, 8) + 0.5;
                        double light = Math.exp(-((x - fx) * (x - fx) + (y - 0.25) * (y - 0.25) + (z - fz) * (z - fz)) * 3.5);
                        double t = smooth(0.35, 0.8, n);
                        ramp(tmp, ramp4, 0.1 + t * 0.45 + light * t * 0.5); mixInto(c, tmp, 1);
                        add(c, accent, light * t * 0.25);
                        double bolt = Math.exp(-Math.abs(fbm(y * 9 + 3, x * 2, z * 2, 5) * 0.6 - (x * fz - z * fx) * 3) * 90) * smooth(-0.1, 0.4, y) * light;
                        add(c, new double[]{1, 1, 1}, bolt * 1.2);
                        break;
                    }
                    default: { // Void: soft gradient + thin light rays
                        double g = 0.5 + 0.5 * y;
                        ramp(tmp, ramp4, 0.05 + 0.25 * Math.pow(1 - Math.abs(y), 3)); mixInto(c, tmp, 1);
                        double a = Math.atan2(z, x);
                        double beams = Math.pow(0.5 + 0.5 * Math.sin(a * 9 + fbm(Math.cos(a) * 3, Math.sin(a) * 3, 2, 3) * 3), 18) * Math.exp(-Math.abs(y) * 4);
                        add(c, pal[3], beams * 0.25);
                        add(c, accent, Math.exp(-Math.abs(y) * 22) * 0.18 * g);
                        break;
                    }
                }

                // darken below the horizon slightly (the ground isn't visible but keep the bottom balanced)
                if (design != 7) {
                    double dk = 0.35 + 0.65 * hz;
                    c[0] *= dk; c[1] *= dk; c[2] *= dk;
                }
                R[k] = (float) c[0]; G[k] = (float) c[1]; B[k] = (float) c[2];
            }
        });

        // star layers
        double starBright = design == 6 ? 0.25 : (design == 13 ? 0.15 : 1.0);
        double minY = (design == 6 || design == 13) ? 0.15 : -0.3;
        if (design != 2) {
            stars(R, G, B, W, H, seed + 1, (int) (W * H / 220.0 * (design == 12 ? 0.6 : 1)), starC, minY, starBright * 0.8, false);
            stars(R, G, B, W, H, seed + 2, design == 12 ? 0 : 180, starC, minY, starBright * 1.2, true);
        } else {
            stars(R, G, B, W, H, seed + 1, W * H / 600, starC, -0.1, 0.5, false);
        }
        if (design == 12) galaxies(R, G, B, W, H, seed + 3, pal);

        // tone mapping + slight dither (no banding) -> ARGB
        int[] out = new int[W * H];
        Random dith = new Random(seed ^ 0x5DEECE66DL);
        for (int k = 0; k < out.length; k++) {
            int rr = tone(R[k], dith), gg = tone(G[k], dith), bb = tone(B[k], dith);
            out[k] = 0xFF000000 | (rr << 16) | (gg << 8) | bb;
        }
        return out;
    }

    private static int tone(float v, Random d) {
        double x = v;
        x = x / (1 + 0.25 * x);                 // soft peak (so the bright ones don't blow out)
        x = Math.pow(clamp(x), 1 / 1.05);
        int q = (int) (x * 255 + d.nextDouble() - 0.5 + 0.5);
        return Math.max(0, Math.min(255, q));
    }

    /** Projects (x,y,z) onto the local plane around the focus direction: {u, v, forward} (scaled by scale). */
    private static double[] local(double x, double y, double z, double fx, double fy, double fz, double scale) {
        double l = Math.sqrt(fx * fx + fy * fy + fz * fz); fx /= l; fy /= l; fz /= l;
        // right = up x f, up = f x right
        double rx = fz, ry = 0, rz = -fx;
        double rl = Math.sqrt(rx * rx + rz * rz); if (rl < 1e-6) { rx = 1; rl = 1; }
        rx /= rl; rz /= rl;
        double ux = fy * rz - fz * ry, uy = fz * rx - fx * rz, uz = fx * ry - fy * rx;
        double fwd = x * fx + y * fy + z * fz;
        return new double[]{(x * rx + y * ry + z * rz) / scale, (x * ux + y * uy + z * uz) / scale, fwd};
    }

    private static double blob(double[] uv, double size, double off) {
        if (uv[2] <= 0) return 0;
        double d = Math.sqrt(uv[0] * uv[0] + uv[1] * uv[1]) / size;
        double n = fbm(uv[0] * 3 + off, uv[1] * 3, off, 7) + 0.5;
        double w = fbm(uv[0] * 1.5, uv[1] * 1.5 + off, 9, 4);
        return clamp(Math.exp(-(d + w * 0.8) * (d + w * 0.8) * 2.2) * (0.35 + 1.0 * n));
    }

    private static void galaxies(float[] R, float[] G, float[] B, int W, int H, long seed, double[][] pal) {
        Random rnd = new Random(seed);
        for (int n = 0; n < 900; n++) {
            double y = rnd.nextDouble() * 2 - 1;
            if (y < -0.3) continue;
            double lon = rnd.nextDouble() * Math.PI * 2, lat = Math.asin(y);
            double px = lon / (Math.PI * 2) * W, py = (0.5 - lat / Math.PI) * H;
            double size = 1.2 + Math.pow(rnd.nextDouble(), 4) * 7;
            double ang = rnd.nextDouble() * Math.PI, ell = 0.25 + rnd.nextDouble() * 0.75;
            double[] col = rnd.nextBoolean() ? pal[3] : pal[4];
            double bri = 0.25 + rnd.nextDouble() * 0.5;
            double stretch = 1 / Math.max(0.1, Math.cos(lat));
            int rad = (int) Math.ceil(size * 3);
            for (int dy = -rad; dy <= rad; dy++) {
                int yy = (int) py + dy; if (yy < 0 || yy >= H) continue;
                for (int dx = (int) (-rad * stretch); dx <= rad * stretch; dx++) {
                    int xx = Math.floorMod((int) px + dx, W);
                    double ax = dx / stretch, ay = dy;
                    double qx = ax * Math.cos(ang) + ay * Math.sin(ang), qy = (-ax * Math.sin(ang) + ay * Math.cos(ang)) / ell;
                    double d2 = (qx * qx + qy * qy) / (size * size);
                    double v = bri * (Math.exp(-d2 * 3) + 0.8 * Math.exp(-d2 * 40));
                    if (v < 0.003) continue;
                    int k = yy * W + xx;
                    R[k] += (float) (v * (col[0] * 0.7 + 0.3)); G[k] += (float) (v * (col[1] * 0.7 + 0.3)); B[k] += (float) (v * (col[2] * 0.7 + 0.3));
                }
            }
        }
    }

    /** Star trails: arcs around the pole; stars bucketed by pole distance. */
    private static float[] buildTrails(int W, int H, long seed, double px, double py, double pz) {
        Random rnd = new Random(seed + 99);
        int bins = 4096;
        java.util.List<double[]>[] byRho = new java.util.ArrayList[bins];
        for (int i = 0; i < bins; i++) byRho[i] = new java.util.ArrayList<>();
        int N = 2600;
        for (int n = 0; n < N; n++) {
            double rho = Math.acos(1 - rnd.nextDouble() * 1.6);        // angular distance to the pole
            double th0 = rnd.nextDouble() * Math.PI * 2;
            double len = 0.35 + rnd.nextDouble() * 0.45;                  // arc length (radians)
            double bri = 0.06 + Math.pow(rnd.nextDouble(), 4) * 0.9;
            double hue = rnd.nextDouble();
            int b = (int) (rho / Math.PI * bins);
            byRho[Math.min(bins - 1, b)].add(new double[]{rho, th0, len, bri, hue});
        }
        // local axes for the pole
        double rx = pz, rz = -px, rl = Math.sqrt(rx * rx + rz * rz); rx /= rl; rz /= rl; double ry = 0;
        double ux = py * rz - pz * ry, uy = pz * rx - px * rz, uz = px * ry - py * rx;
        float[] out = new float[W * H];
        for (int j = 0; j < H; j++) {
            double lat = Math.PI / 2 - (j + 0.5) / H * Math.PI;
            double cl = Math.cos(lat), y = Math.sin(lat);
            if (y < -0.08) continue;
            double pixRad = Math.PI / H; // angular size of a pixel
            for (int i = 0; i < W; i++) {
                double lon = (i + 0.5) / W * Math.PI * 2;
                double x = cl * Math.cos(lon), z = cl * Math.sin(lon);
                double d = x * px + y * py + z * pz;
                double rho = Math.acos(Math.max(-1, Math.min(1, d)));
                double th = Math.atan2(x * ux + y * uy + z * uz, x * rx + y * ry + z * rz);
                int b = (int) (rho / Math.PI * bins);
                double sum = 0;
                for (int q = Math.max(0, b - 2); q <= Math.min(bins - 1, b + 2); q++) {
                    for (double[] s : byRho[q]) {
                        double dr = (rho - s[0]) / (pixRad * 0.7);
                        double w = Math.exp(-dr * dr);
                        if (w < 0.01) continue;
                        double dt = th - s[1];
                        dt = dt - Math.floor(dt / (Math.PI * 2)) * Math.PI * 2;
                        if (dt > s[2]) continue;
                        double fadeT = 0.4 + 0.6 * (dt / s[2]);        // brightens toward the tip of the trail
                        sum += w * s[3] * fadeT;
                    }
                }
                out[j * W + i] = (float) (sum * smooth(-0.08, 0.05, y));
            }
        }
        return out;
    }
}
